/* Français / español : traduction complète, choix mémorisé. */
(function(){
 const translations={"Benjamin Gonzalez — Architecte d'intérieur, Pays Basque": "Benjamin Gonzalez — Interiorista, País Vasco", "Architecte d'intérieur au Pays Basque. Cinq ans d'expérience dont trois en maison neuve haut de gamme. Conception, plans techniques, 3D et suivi de chantier.": "Interiorista en el País Vasco. Cinco años de experiencia, tres de ellos en viviendas de obra nueva de alta gama. Diseño, planos técnicos, 3D y seguimiento de obra.", "Benjamin Gonzalez — Architecte d'intérieur": "Benjamin Gonzalez — Interiorista", "Conception, plans, 3D et suivi de chantier au Pays Basque. De l'esquisse à la livraison.": "Diseño, planos, 3D y seguimiento de obra en el País Vasco. Del primer boceto a la entrega.", "Aller au contenu": "Ir al contenido", "Benjamin Gonzalez — Accueil": "Benjamin Gonzalez — Inicio", "Benjamin Gonzalez": "Benjamin Gonzalez", "Architecte d’intérieur": "Interiorista", "Ouvrir le menu": "Abrir el menú", "Navigation principale": "Navegación principal", "Origine": "Origen", "Services": "Servicios", "Matières": "Materiales", "Projets": "Proyectos", "Contact": "Contacto", "Pays Basque — Agencement & décoration": "País Vasco — Diseño de espacios y decoración", "UN REGARD ANCRÉ AU PAYS BASQUE": "UNA MIRADA ARRAIGADA EN EL PAÍS VASCO", "Une histoire, un projet, un chantier. Un seul interlocuteur.": "Una historia, un proyecto, una obra. Un único interlocutor.", "Architecte d'intérieur au Pays Basque, cinq ans de métier dont trois en maison neuve haut de gamme. Je conçois votre projet et je le tiens jusqu'au bout : croquis, plans techniques, 3D, chiffrage et suivi des artisans.": "Interiorista en el País Vasco, con cinco años de experiencia, tres de ellos en viviendas de obra nueva de alta gama. Diseño tu proyecto y te acompaño hasta el final: bocetos, planos técnicos, 3D, estimación de costes y seguimiento de los profesionales.", "Parler de votre projet": "Hablemos de tu proyecto", "Voir les projets": "Ver los proyectos", "Faire défiler": "Desplazarse hacia abajo", "Découvrir": "Descubrir", "Intérieur conçu par Benjamin Gonzalez": "Interior diseñado por Benjamin Gonzalez", "« La forme suit la fonction. La forme et la fonction devraient faire un, unies dans une union spirituelle. »": "« La forma sigue a la función. La forma y la función deberían ser una sola, unidas en una unión espiritual. »", "Frank Lloyd Wright": "Frank Lloyd Wright", "Mon expérience": "Mi experiencia", "5 ans": "5 años", "de conception et de chantier": "de diseño y obra", "3 ans": "3 años", "en maison neuve haut de gamme": "en viviendas de obra nueva de alta gama", "Un interlocuteur": "Un interlocutor", "du premier croquis aux finitions": "del primer boceto a los acabados", "ORIGINE": "ORIGEN", "Cinq ans à faire tenir ensemble le dessin et le chantier.": "Cinco años uniendo el diseño y la obra.", "J'exerce depuis cinq ans, dont trois passés en entreprise sur des projets de maisons neuves haut de gamme. J'y ai appris ce qui sépare une belle image d'un projet qui se construit : la contrainte technique, le calendrier des corps d'état, le budget qui bouge, et la décision à prendre en une journée pour ne pas bloquer une équipe.": "Llevo cinco años ejerciendo, tres de ellos en una empresa dedicada a proyectos de viviendas de obra nueva de alta gama. Allí aprendí qué separa una imagen bonita de un proyecto que se construye: las limitaciones técnicas, los plazos de cada oficio, un presupuesto que evoluciona y las decisiones que hay que tomar en un día para no detener a un equipo.", "C'est de là que vient ma façon de travailler. Je dessine d'abord à la main, parce que rien ne va aussi vite pour tester un parti pris et le montrer à un client. Puis je passe en modélisation 3D et en plans cotés, ceux que les artisans lisent réellement sur place. Le même projet, du premier trait au dernier joint de finition.": "De ahí nace mi forma de trabajar. Primero dibujo a mano, porque nada es tan rápido para explorar una idea y mostrársela a un cliente. Después paso al modelado 3D y a los planos acotados, los que los profesionales utilizan realmente en obra. El mismo proyecto, desde el primer trazo hasta el último acabado.", "Je ne rends pas une intention : je rends un projet chiffré, dessiné au millimètre, et je reste là pendant les travaux.": "No entrego solo una intención: entrego un proyecto valorado, dibujado al milímetro, y sigo presente durante la obra.", "UNE CULTURE DU DÉTAIL": "UNA CULTURA DEL DETALLE", "Le design italien,": "El diseño italiano,", "une influence vécue.": "una influencia vivida.", "Mon expérience a façonné ce goût pour les belles matières, les proportions et les détails de mobilier. J’aime quand une menuiserie, un éclairage ou une courbe apporte autant à l’usage qu’à l’élégance d’un lieu. Cette sensibilité nourrit mes projets, avec un ancrage résolument basque.": "Mi experiencia ha formado mi gusto por los materiales, las proporciones y los detalles del mobiliario. Me gusta que un elemento de carpintería, una luz o una curva aporten tanto al uso como a la elegancia de un espacio. Esta sensibilidad nutre mis proyectos, con un profundo arraigo vasco.", "Ce que je fais moi-même": "De qué me encargo personalmente", "Conception et création": "Diseño y creación", "Croquis et esquisses à la main": "Bocetos y croquis a mano", "Direction artistique, planches d'ambiance": "Dirección artística y paneles de inspiración", "Choix des matériaux, couleurs, lumières": "Selección de materiales, colores e iluminación", "Mobilier sur mesure et stylisme": "Mobiliario a medida y estilismo", "Technique et chantier": "Técnica y obra", "Relevés, plans 2D cotés, plans d'exécution": "Toma de medidas, planos 2D acotados y planos de ejecución", "Modélisation 3D et rendus": "Modelado 3D e infografías", "Estimation budgétaire, consultation des entreprises": "Estimación del presupuesto y consulta a empresas", "Coordination des artisans et suivi de chantier": "Coordinación de profesionales y seguimiento de obra", "Les outils": "Las herramientas", "AutoCAD": "AutoCAD", "Plans 2D et exécution": "Planos 2D y de ejecución", "Archicad": "Archicad", "Maquette numérique": "Maqueta digital", "SketchUp": "SketchUp", "Modélisation 3D": "Modelado 3D", "Twinmotion": "Twinmotion", "Rendus et visites virtuelles": "Infografías y visitas virtuales", "SERVICES": "SERVICIOS", "DU CONSEIL À LA RÉALISATION": "DEL ASESORAMIENTO A LA REALIZACIÓN", "Le bon regard.": "La mirada adecuada.", "Le bon accompagnement.": "El acompañamiento adecuado.", "Une pièce à repenser, un logement locatif à aménager ou tout un lieu à transformer : nous définissons une mission adaptée à votre projet.": "Una estancia que replantear, una vivienda de alquiler que amueblar o un espacio completo que transformar: definimos un servicio adaptado a tu proyecto.", "MISSION 01 · PRENDRE UNE DIRECTION": "SERVICIO 01 · DEFINIR EL RUMBO", "Visite conseil": "Visita de asesoramiento", "à partir de 350 €": "desde 350 €", "Un regard professionnel pour débloquer vos choix et poser une intention claire.": "Una mirada profesional para ayudarte a decidir y definir una intención clara.", "Rendez-vous sur place jusqu’à 2 heures": "Visita al espacio de hasta 2 horas", "Lecture de l’espace et conseils d’agencement": "Análisis del espacio y consejos de distribución", "Orientations de couleurs, matières et éclairage": "Orientaciones sobre colores, materiales e iluminación", "Synthèse écrite des recommandations": "Resumen escrito de las recomendaciones", "Sans plans ni vues 3D. Planche d’ambiance et sélection détaillée de mobilier proposées en complément sur devis.": "No incluye planos ni vistas 3D. Panel de inspiración y selección detallada de mobiliario disponibles como servicios adicionales bajo presupuesto.", "Parlons de cette mission": "Hablemos de este servicio", "MISSION 02 · DONNER FORME": "SERVICIO 02 · DAR FORMA", "Conception d’une pièce": "Diseño de una estancia", "à partir de 1 200 €": "desde 1 200 €", "Un espace pensé dans son ensemble : circulation, ambiance et mobilier.": "Un espacio pensado en su conjunto: circulación, ambiente y mobiliario.", "Relevé et plan d’état des lieux de la pièce": "Toma de medidas y plano del estado actual de la estancia", "Deux pistes d’agencement, puis développement de la solution retenue": "Dos propuestas de distribución y desarrollo de la opción elegida", "Planche d’ambiance et palette matières": "Panel de inspiración y selección de materiales", "Deux vues 3D de la proposition retenue": "Dos vistas 3D de la propuesta elegida", "Sélection de revêtements, mobilier et éclairage": "Selección de revestimientos, mobiliario e iluminación", "Un cycle d’ajustements après présentation": "Una ronda de ajustes tras la presentación", "Base pour une pièce jusqu’à 20 m², hors étude technique complexe. Cuisine, salle de bain, dessins d’exécution et mobilier sur mesure détaillé : devis adapté.": "Base para una estancia de hasta 20 m², sin estudio técnico complejo. Cocinas, baños, planos de ejecución y mobiliario a medida detallado: presupuesto adaptado.", "MISSION 03 · REPENSER L’ENSEMBLE": "SERVICIO 03 · REPENSAR EL CONJUNTO", "Conception globale": "Diseño integral", "à partir de 75 € / m²": "desde 75 € / m²", "Une vision cohérente de votre intérieur, jusque dans ses proportions et ses associations de matières.": "Una visión coherente de tu interior, hasta en sus proporciones y combinaciones de materiales.", "Relevé et analyse des espaces concernés": "Toma de medidas y análisis de los espacios", "Redistribution des volumes et plans d’agencement": "Redistribución de volúmenes y planos de distribución", "Direction artistique : matières, couleurs et lumière": "Dirección artística: materiales, colores y luz", "Vues 3D des espaces clés définis au devis": "Vistas 3D de los espacios clave definidos en el presupuesto", "Principes de mobilier intégré et implantations": "Criterios de mobiliario integrado y ubicación", "Estimation prévisionnelle de l’enveloppe travaux": "Estimación inicial del presupuesto de obra", "Deux cycles d’ajustements de la proposition": "Dos rondas de ajustes de la propuesta", "Minimum de mission : 3 000 €. Le prix dépend de la surface et de la complexité. Dossier technique détaillé, consultation des entreprises et démarches administratives : missions complémentaires sur devis.": "Honorarios mínimos: 3 000 €. El precio depende de la superficie y la complejidad. Documentación técnica detallada, consulta a empresas y trámites administrativos: servicios adicionales bajo presupuesto.", "MISSION 04 · CONCRÉTISER": "SERVICIO 04 · HACERLO REALIDAD", "Du dessin au chantier": "Del diseño a la obra", "sur devis": "bajo presupuesto", "Prolonger la conception par une préparation précise et un accompagnement pendant les travaux.": "Dar continuidad al diseño con una preparación precisa y acompañamiento durante la obra.", "Dossier technique et plans détaillés selon la mission": "Documentación técnica y planos detallados según el encargo", "Consultation et analyse des devis des entreprises": "Solicitud y análisis de presupuestos de las empresas", "Coordination avec l’architecte, le constructeur ou les bureaux d’études du projet": "Coordinación con el arquitecto, el constructor o las ingenierías del proyecto", "Calepinages et détails des menuiseries sur mesure": "Despieces y detalles de carpintería a medida", "Planification et coordination des intervenants": "Planificación y coordinación de los profesionales", "Visites de chantier et comptes rendus": "Visitas de obra e informes", "Accompagnement à la réception et suivi des réserves": "Acompañamiento en la recepción y seguimiento de los remates pendientes", "Rénovation ou agencement d’une maison neuve. Honoraires établis selon l’ampleur, la durée et la fréquence des visites. Conception et suivi sont identifiés séparément au devis.": "Reforma o diseño interior de una vivienda de obra nueva. Honorarios según el alcance, la duración y la frecuencia de las visitas. El diseño y el seguimiento se detallan por separado en el presupuesto.", "Prix nets pour les prestations décrites. TVA non applicable, article L.223-3 du Code des impositions des biens et des services (CIBS). Hors travaux, achats et études de tiers. Les éventuels frais de déplacement sont précisés avant engagement. Chaque devis détaille les livrables, les étapes, les délais et les honoraires.": "Precios netos para los servicios descritos. IVA no aplicable conforme al artículo L.223-3 del Código francés de imposición de bienes y servicios (CIBS). No incluye obras, compras ni estudios de terceros. Los posibles gastos de desplazamiento se indican antes de la contratación. Cada presupuesto detalla las entregas, las fases, los plazos y los honorarios.", "MÉTHODE": "MÉTODO", "DU PREMIER ÉCHANGE AUX FINITIONS": "DEL PRIMER CONTACTO A LOS ACABADOS", "Un projet clair.": "Un proyecto claro.", "À chaque étape.": "En cada etapa.", "Une idée prend forme progressivement. Nous avançons ensemble, avec des choix expliqués et des étapes adaptées à votre mission.": "Una idea toma forma poco a poco. Avanzamos juntos, con decisiones explicadas y etapas adaptadas a tu encargo.", "Vous écouter.": "Escucharte.", "Vos envies, vos habitudes, votre lieu de vie. Nous précisons le besoin, le budget et les priorités.": "Tus deseos, tus hábitos, tu espacio. Concretamos las necesidades, el presupuesto y las prioridades.", "Donner forme.": "Dar forma.", "Croquis, matières et volumes : les premières intentions deviennent des plans et des vues 3D.": "Bocetos, materiales y volúmenes: las primeras ideas se convierten en planos y vistas 3D.", "Tout préciser.": "Precisar cada detalle.", "Matériaux, détails techniques et chiffrage se rejoignent pour préparer la réalisation.": "Materiales, detalles técnicos y estimación de costes se unen para preparar la realización.", "Accompagner.": "Acompañarte.", "Selon la mission retenue, je coordonne les artisans et suis les travaux jusqu’aux finitions.": "Según el servicio elegido, coordino a los profesionales y hago el seguimiento de la obra hasta los acabados.", "MATIÈRES": "MATERIALES", "UNE SENSIBILITÉ. UN TERRITOIRE.": "UNA SENSIBILIDAD. UN TERRITORIO.", "La matière se voit.": "La materia se ve.", "Elle se ressent.": "También se siente.", "Mon parcours a durablement façonné mon regard autour du design italien : la générosité des matières, la justesse des proportions, l'attention portée au moindre détail. Dans mes projets, cet héritage dialogue avec la sobriété des intérieurs japonais, tandis que les teintes et les textures puisent dans les paysages du Pays Basque.": "Mi trayectoria ha moldeado mi mirada en torno al diseño italiano: la generosidad de los materiales, la precisión de las proporciones y la atención al más mínimo detalle. En mis proyectos, esta herencia dialoga con la sobriedad de los interiores japoneses, mientras que los tonos y las texturas se inspiran en los paisajes del País Vasco.", "Le vert comme point d’ancrage.": "El verde como vínculo con mis raíces.", "Les sensations comme point de départ.": "Las sensaciones como punto de partida.", "PAYS BASQUE": "PAÍS VASCO", "ANCRAGE & INSPIRATION": "RAÍCES E INSPIRACIÓN", "Explorer les sensations": "Explorar las sensaciones", "Toucher": "Tocar", "Contempler": "Contemplar", "S’envelopper": "Arroparse", "Ressentir": "Sentir", "Projection du séjour : menuiseries aux tons bois et éclairage intégré": "Visualización del salón: carpintería en tonos madera e iluminación integrada", "ÉTUDE D’AMBIANCE · LE BOIS ET LA LUMIÈRE": "ESTUDIO DE AMBIENTE · LA MADERA Y LA LUZ", "LE TOUCHER": "EL TACTO", "Toucher.": "Tocar.", "Sentir la matière.": "Sentir la materia.", "Retrouver la chaleur d’un lieu accueillant. Le bois, ses nuances et son veinage donnent une présence aux volumes, dans l’esprit des intérieurs italiens où le mobilier fait partie de l’architecture.": "Recuperar la calidez de un lugar acogedor. La madera, sus matices y sus vetas dan presencia a los volúmenes, en el espíritu de los interiores italianos donde el mobiliario forma parte de la arquitectura.", "Chêne lumineux ou noyer plus enveloppant : l’essence et la finition se choisissent avec la lumière du lieu.": "Roble luminoso o nogal más envolvente: la especie y el acabado se eligen en diálogo con la luz del espacio.", "Veinage": "Vetas", "Rythme": "Ritmo", "Sur-mesure": "A medida", "Projection de chambre : murs clairs à l’aspect minéral et lumière naturelle": "Visualización del dormitorio: paredes claras de aspecto mineral y luz natural", "ÉTUDE D’AMBIANCE · LES TONS MINÉRAUX": "ESTUDIO DE AMBIENTE · LOS TONOS MINERALES", "LE REGARD": "LA MIRADA", "Contempler.": "Contemplar.", "Laisser le regard respirer.": "Dejar respirar la mirada.", "Apaiser le regard. Des tons pierre, des surfaces mates et une lumière douce composent un fond calme, où chaque objet peut trouver sa place.": "Calmar la mirada. Tonos piedra, superficies mates y una luz suave componen un fondo sereno donde cada objeto encuentra su lugar.", "Des tons ivoire et pierre pour accompagner le vert profond, avec des finitions choisies selon les usages et l’entretien.": "Tonos marfil y piedra que acompañan al verde profundo, con acabados elegidos según el uso y el mantenimiento.", "Grain": "Grano", "Relief": "Relieve", "Matité": "Acabado mate", "Projection de chambre : linge gris bleuté, coussins et tête de lit en bois": "Visualización del dormitorio: ropa de cama gris azulada, cojines y cabecero de madera", "ÉTUDE D’AMBIANCE · LES TEXTURES DOUCES": "ESTUDIO DE AMBIENTE · LAS TEXTURAS SUAVES", "LE CONFORT": "EL CONFORT", "S’envelopper.": "Arroparse.", "Avoir envie de rester.": "Querer quedarse.", "Avoir envie de toucher, de s’asseoir, de rester. Un rideau qui filtre le jour et une étoffe souple rendent l’espace plus intime, plus confortable.": "Tener ganas de tocar, sentarse y quedarse. Una cortina que filtra la luz y una tela suave hacen el espacio más íntimo y confortable.", "Lin, laine ou tissage plus dense : je travaille leurs textures et leurs nuances avec celles du bois et de la pierre.": "Lino, lana o tejidos más densos: combino sus texturas y sus matices con los de la madera y la piedra.", "Souplesse": "Suavidad", "Confort": "Confort", "Projection d’une verrière noire aux lignes fines devant une salle à manger en bois": "Visualización de una mampara acristalada negra de líneas finas frente a un comedor de madera", "ÉTUDE D’AMBIANCE · LA FINESSE DU TRAIT": "ESTUDIO DE AMBIENTE · LA FINURA DEL TRAZO", "L’ÉMOTION": "LA EMOCIÓN", "Ressentir.": "Sentir.", "L’émotion d’un détail.": "La emoción de un detalle.", "Sentir qu’un lieu a sa personnalité. Une ligne sombre, une poignée dessinée, une lumière sculpturale : un détail bien choisi suffit à donner du caractère à l’ensemble.": "Sentir que un lugar tiene personalidad. Una línea oscura, un tirador diseñado, una luz escultórica: un detalle bien elegido basta para dar carácter al conjunto.", "Le contraste du noir et des teintes naturelles donne de la précision à l’ensemble, jusque dans les poignées et les luminaires.": "El contraste del negro y los tonos naturales aporta precisión al conjunto, hasta en los tiradores y las luminarias.", "Finesse": "Finura", "Contraste": "Contraste", "Détail": "Detalle", "LE FIL CONDUCTEUR": "EL HILO CONDUCTOR", "Là où la lumière": "Donde la luz", "rencontre la matière": "se encuentra con la materia", "Trouvons votre équilibre": "Encontremos tu equilibrio", "VISIONS": "VISIONES", "DE L’ARCHITECTURE AU QUOTIDIEN": "DE LA ARQUITECTURA A LO COTIDIANO", "Un lieu.": "Un lugar.", "Une façon de vivre.": "Una forma de vivir.", "Respecter le caractère d’une maison, trouver la justesse d’un agencement, faire entrer la lumière. Ces visions explorent le lien entre le lieu, ses volumes et la vie qui s’y installe.": "Respetar el carácter de una casa, acertar con la distribución, dejar entrar la luz. Estas visiones exploran la relación entre el lugar, sus volúmenes y la vida que lo habita.", "Agrandir : Habiter une histoire.": "Ampliar: Habitar una historia.", "Projection d’une maison de caractère à colombages, toiture en tuiles et galerie à arcades": "Visualización de una casa tradicional con entramado, tejado de teja y galería de arcos", "VISION D’ARCHITECTURE · 01": "VISIÓN ARQUITECTÓNICA · 01", "Habiter une histoire.": "Habitar una historia.", "Façade, proportions et caractère basque": "Fachada, proporciones y carácter vasco", "Agrandir : La simplicité, habitée.": "Ampliar: La sencillez, habitada.", "Projet locatif : projection d’une cuisine aux façades beige avec table ronde en bois et lumière naturelle": "Proyecto para alquiler: visualización de una cocina con frentes beige, mesa redonda de madera y luz natural", "PROJET LOCATIF · CUISINE & REPAS": "PROYECTO PARA ALQUILER · COCINA Y COMEDOR", "La simplicité, habitée.": "La sencillez, habitada.", "Un espace repas convivial, pensé pour la location": "Un comedor acogedor, pensado para el alquiler", "Agrandir : Tout trouve sa place.": "Ampliar: Todo encuentra su lugar.", "Projet locatif : projection d’un espace de vie avec cuisine, étagères en bois, table ronde et banquette": "Proyecto para alquiler: visualización de un espacio con cocina, estantes de madera, mesa redonda y banco", "PROJET LOCATIF · AGENCEMENT": "PROYECTO PARA ALQUILER · DISTRIBUCIÓN", "Tout trouve sa place.": "Todo encuentra su lugar.", "Cuisine, rangements et salon réunis dans un logement locatif": "Cocina, almacenaje y salón reunidos en una vivienda de alquiler", "UNE COMPÉTENCE AU SERVICE DES PROPRIÉTAIRES": "UNA COMPETENCIA AL SERVICIO DE LOS PROPIETARIOS", "Le locatif mérite": "El alquiler también merece", "le sens du détail.": "atención al detalle.", "Concevoir un logement pour la location, c’est concilier confort des occupants et contraintes du propriétaire. Je travaille l’agencement pour optimiser les surfaces, intégrer les rangements et créer une ambiance accueillante, avec des matériaux choisis pour leur résistance, leur entretien et le budget du projet.": "Diseñar una vivienda de alquiler significa conciliar el confort de sus ocupantes con las necesidades del propietario. Trabajo la distribución para optimizar la superficie, integrar almacenaje y crear un ambiente acogedor, con materiales elegidos por su resistencia, mantenimiento y adecuación al presupuesto.", "Parlons de votre projet locatif": "Hablemos de tu proyecto de alquiler", "Agrandir : Penser le lieu dans son ensemble.": "Ampliar: Pensar el espacio en su conjunto.", "Vue 3D de dessus d’un appartement avec séjour, cuisine, chambre et salle de bain": "Vista 3D superior de una vivienda con salón, cocina, dormitorio y baño", "PROJECTION D’INTÉRIEUR · 04": "VISUALIZACIÓN DE INTERIORES · 04", "Penser le lieu dans son ensemble.": "Pensar el espacio en su conjunto.", "Vue d’ensemble de l’agencement": "Vista general de la distribución", "Projections et visuels d’ambiance.": "Visualizaciones y propuestas de ambiente.", "Imaginons votre intérieur": "Imaginemos tu interior", "PROJETS": "PROYECTOS", "Réalisations récentes.": "Proyectos recientes.", "Des chantiers réels, photographiés sur place. Cette page s'étoffe au fil des livraisons.": "Obras reales, fotografiadas en el lugar. Esta página crece con cada entrega.", "Salle de bain rénovée à Anglet": "Baño reformado en Anglet", "Salle de bain — Anglet": "Baño — Anglet", "Agencement & décoration": "Diseño de espacios y decoración", "ÉCHANGE": "CONVERSACIÓN", "AVANT DE SE RENCONTRER": "ANTES DE CONOCERNOS", "Les premières questions.": "Las primeras preguntas.", "Mon projet est encore flou. Peut-on en parler ?": "Mi proyecto aún no está definido. ¿Podemos hablarlo?", "Bien sûr. Quelques envies, des photos ou simplement une difficulté dans votre logement suffisent pour commencer l’échange.": "Por supuesto. Algunas ideas, fotografías o simplemente una dificultad en tu vivienda bastan para iniciar la conversación.", "Puis-je vous confier une seule pièce ?": "¿Puedo encargarte una sola estancia?", "Oui. La conception d’une pièce commence à 1 200 € pour le périmètre décrit. Pour une cuisine, une salle de bain ou une pièce techniquement complexe, je prépare un devis adapté.": "Sí. El diseño de una estancia parte de 1 200 € para el alcance descrito. Para una cocina, un baño o una estancia técnicamente compleja, preparo un presupuesto adaptado.", "Comment est défini le montant de votre mission ?": "¿Cómo se calculan tus honorarios?", "Les tarifs présentés correspondent aux prestations décrites. Après un premier échange, je précise le périmètre et les honoraires dans un devis. La visite conseil est une prestation distincte, à partir de 350 €.": "Las tarifas indicadas corresponden a los servicios descritos. Tras un primer contacto, concreto el alcance y los honorarios en un presupuesto. La visita de asesoramiento es un servicio independiente, desde 350 €.", "CONTACT": "CONTACTO", "En parler, échanger, se rencontrer.": "Hablar, compartir, conocernos.", "Particulier ou professionnel, rénovation d'un appartement, boutique à concevoir ou maison neuve à agencer : décrivez votre projet en quelques lignes, même s'il est encore flou. Je réponds sous 48 heures ouvrées.": "Particular o profesional, reforma de un piso, diseño de una tienda o distribución de una casa nueva: describe tu proyecto en unas líneas, aunque aún no esté definido. Respondo en un plazo de 48 horas laborables.", "Téléphone": "Teléfono", "E-mail": "Correo electrónico", "gonzalez_benjamin@outlook.fr": "gonzalez_benjamin@outlook.fr", "Instagram": "Instagram", "@benjamin.gonzalez_designer": "@benjamin.gonzalez_designer", "Écrivez-moi": "Escríbeme", "Les champs marqués d'un astérisque sont nécessaires pour vous répondre.": "Los campos marcados con un asterisco son necesarios para poder responderte.", "Nom et prénom *": "Nombre y apellidos *", "E-mail *": "Correo electrónico *", "Type de projet": "Tipo de proyecto", "Autre / je ne sais pas encore": "Otro / aún no lo sé", "Votre projet *": "Tu proyecto *", "Surface, ville, échéance souhaitée, ce que vous avez en tête…": "Superficie, ciudad, plazo deseado, lo que tienes en mente…", "Ne pas remplir": "No rellenar", "Envoyer le message": "Enviar el mensaje", "Visuel agrandi": "Imagen ampliada", "Fermer le visuel": "Cerrar la imagen", "Fermer": "Cerrar", "Revenir à l’accueil": "Volver al inicio", "Benjamin Gonzalez — Architecte d’intérieur": "Benjamin Gonzalez — Interiorista", "Prendre contact": "Contactar", "Benjamin Gonzalez, architecte d’intérieur au Pays Basque": "Benjamin Gonzalez, interiorista en el País Vasco", "Choisir la langue": "Elegir el idioma", "Image indisponible": "Imagen no disponible", "Ceci est un aperçu. Pour me contacter, utilisez les liens e-mail ou téléphone.": "Esta es una vista previa. Para contactar conmigo, utiliza los enlaces de correo electrónico o teléfono.", "Il manque le nom, l'e-mail ou le message.": "Falta el nombre, el correo electrónico o el mensaje.", "L'adresse e-mail n'est pas valide.": "La dirección de correo electrónico no es válida.", "Envoi en cours…": "Enviando…", "Message envoyé. Je vous réponds sous 48 heures ouvrées.": "Mensaje enviado. Te responderé en un plazo de 48 horas laborables.", "L'envoi a échoué. Écrivez-moi directement à": "No se ha podido enviar el mensaje. Escríbeme directamente a", "ou appelez le": "o llama al", "Vos informations servent à répondre à votre demande. Le formulaire utilise Web3Forms pour transmettre votre message par e-mail.": "Tus datos sirven para responder a tu solicitud. El formulario utiliza Web3Forms para enviar tu mensaje por correo electrónico.", "Architecte d’intérieur à Anglet — Benjamin Gonzalez": "Interiorista en Anglet — Benjamin Gonzalez", "Benjamin Gonzalez, architecte d’intérieur à Anglet et au Pays Basque. Agencement, rénovation, projets locatifs, plans et vues 3D. Une sensibilité italienne et japonaise.": "Benjamin Gonzalez, interiorista en Anglet y el País Vasco. Diseño, reformas, viviendas de alquiler, planos y vistas 3D. Sensibilidad italiana y japonesa.", "Le regard": "La mirada", "Parlons de votre projet": "Hablemos de tu proyecto", "ARCHITECTURE D’INTÉRIEUR · ANGLET, PAYS BASQUE": "INTERIORISMO · ANGLET, PAÍS VASCO", "rencontre la matière.": "se encuentra con la materia.", "Des intérieurs sensibles.": "Interiores con sensibilidad.", "Des espaces faits pour vous.": "Espacios hechos para ti.", "Explorer les projets": "Explorar los proyectos", "Projection d’un séjour avec bibliothèque sur mesure en bois et lumière intégrée": "Visualización de un salón con biblioteca de madera a medida e iluminación integrada", "LE BOIS. LA LUMIÈRE. LE SENS DU DÉTAIL.": "LA MADERA. LA LUZ. EL SENTIDO DEL DETALLE.", "Étude d’intérieur · Visualisation 3D": "Estudio de interior · Visualización 3D", "La générosité italienne. La sérénité japonaise. L’ancrage basque.": "La generosidad italiana. La serenidad japonesa. Las raíces vascas.", "Découvrir mon approche": "Descubrir mi enfoque", "Une salle de bain. Un nouvel équilibre.": "Un baño. Un nuevo equilibrio.", "À Anglet, une réalisation qui prolonge le dessin jusque dans les détails du quotidien.": "En Anglet, un proyecto que lleva el diseño hasta los detalles cotidianos.", "Un regard personnel.": "Una mirada personal.", "Une présence à chaque étape.": "A tu lado en cada etapa.", "Je suis Benjamin Gonzalez, architecte d’intérieur à Anglet. Je dessine des lieux où la beauté des matières accompagne la simplicité des usages.": "Soy Benjamin Gonzalez, interiorista en Anglet. Diseño espacios donde la belleza de los materiales acompaña la sencillez de los usos.", "Cinq ans de métier, dont trois en maison neuve haut de gamme, ont construit ma façon de travailler : relier l’intention, la précision des plans et la réalité du chantier.": "Cinco años de experiencia, tres de ellos en viviendas de obra nueva de alta gama, han definido mi forma de trabajar: unir la intención, la precisión de los planos y la realidad de la obra.", "Du premier trait aux finitions, un seul interlocuteur.": "Del primer trazo a los acabados, un único interlocutor.", "Savoir-faire et outils": "Experiencia y herramientas", "Le détail de la mission": "El detalle del servicio", "LE DESSIN": "EL DIBUJO", "DONNER FORME À UNE INTENTION": "DAR FORMA A UNA INTENCIÓN", "Du trait": "Del trazo", "à la matière.": "a la materia.", "Un même espace, deux lectures. Faites glisser le curseur pour passer du dessin à la visualisation des matières et de la lumière.": "Un mismo espacio, dos lecturas. Desliza el control para pasar del dibujo a la visualización de los materiales y de la luz.", "Visualisation du séjour en bois clair": "Visualización del salón en madera clara", "Dessin du même séjour et de ses menuiseries": "Dibujo del mismo salón y de su carpintería", "Le dessin": "El dibujo", "La projection": "La visualización", "Explorer du dessin à la projection": "Explorar del dibujo a la visualización", "Étude de conception · Dessin et visualisation 3D": "Estudio de diseño · Dibujo y visualización 3D", "Des espaces qui dialoguent.": "Espacios que dialogan.", "Vue du séjour et de la cuisine, arches claires, chêne et claustra en terre cuite": "Vista del salón y la cocina, arcos claros, roble y celosía de terracota", "Agrandir : Des espaces qui dialoguent.": "Ampliar: Espacios que dialogan.", "La douceur des courbes.": "La suavidad de las curvas.", "Salon aux murs ivoire, bibliothèque en chêne et canapé vert profond": "Salón con paredes marfil, biblioteca de roble y sofá verde oscuro", "Agrandir : La douceur des courbes.": "Ampliar: La suavidad de las curvas.", "La lumière en partage.": "La luz compartida.", "Cuisine en chêne avec îlot clair et séparation en briques de verre": "Cocina de roble con isla clara y separación de bloques de vidrio", "Agrandir : La lumière en partage.": "Ampliar: La luz compartida.", "Se retrouver autour du bois.": "Reunirse en torno a la madera.", "Salle à manger avec table en chêne, banquette et claustra en terre cuite": "Comedor con mesa de roble, banco y celosía de terracota", "Agrandir : Se retrouver autour du bois.": "Ampliar: Reunirse en torno a la madera.", "Des passages, des perspectives.": "Pasos y perspectivas.", "Arches ouvertes sur le salon avec cheminée sombre et claustra ajouré": "Arcos abiertos al salón con chimenea oscura y celosía calada", "Agrandir : Des passages, des perspectives.": "Ampliar: Pasos y perspectivas.", "Le détail habite les murs.": "El detalle habita las paredes.", "Bibliothèque en chêne éclairée, canapé vert et grande baie vitrée": "Biblioteca de roble iluminada, sofá verde y gran ventanal", "Agrandir : Le détail habite les murs.": "Ampliar: El detalle habita las paredes.", "Filtrer sans fermer.": "Filtrar sin cerrar.", "Cuisine et îlot aux lignes douces, chêne et briques de verre ondulées": "Cocina e isla de líneas suaves, roble y bloques de vidrio ondulado", "Agrandir : Filtrer sans fermer.": "Ampliar: Filtrar sin cerrar.", "À DÉCOUVRIR": "POR DESCUBRIR", "PROJET D’INTÉRIEUR · VISUELS DE CONCEPTION": "PROYECTO DE INTERIOR · VISUALIZACIONES", "Chêne, courbes": "Roble, curvas", "et lumière.": "y luz.", "Des arches qui relient les espaces, un chêne chaleureux et une lumière qui traverse le verre. Ce projet fait dialoguer la générosité du design italien avec la simplicité des lignes et le plaisir d’habiter.": "Arcos que conectan los espacios, un roble cálido y una luz que atraviesa el vidrio. Este proyecto combina la generosidad del diseño italiano con la sencillez de las líneas y el placer de habitar.", "La chaleur du chêne": "La calidez del roble", "Le rythme des arches": "El ritmo de los arcos", "La transparence du verre": "La transparencia del vidrio", "Explorer les 4 autres vues": "Explorar las otras 4 vistas", "Réduire la galerie": "Cerrar la galería", "Séjour · Salle à manger · Cuisine": "Salón · Comedor · Cocina", "Parlons de votre intérieur": "Hablemos de tu interior", "Vos informations servent uniquement à vous répondre et ne sont jamais transmises à des tiers.": "Tus datos se utilizan únicamente para responderte y nunca se comparten con terceros.", "Architecte d’intérieur à Anglet | Benjamin Gonzalez": "Interiorista en Anglet | Benjamin Gonzalez", "Benjamin Gonzalez, architecte d’intérieur à Anglet : rénovation, aménagement et décoration à Biarritz, Bayonne et sur la Côte Basque. Parlons de votre projet.": "Benjamin Gonzalez, interiorista en Anglet: reformas, distribución y decoración en Biarritz, Bayona y la Costa Vasca. Hablemos de tu proyecto.", "Architecte d’intérieur à Anglet, sur la Côte Basque": "Interiorista en Anglet, en la Costa Vasca", "Basé à Anglet, j’accompagne vos projets de rénovation, d’aménagement et de décoration à Biarritz, Bayonne et sur la Côte Basque. Maison, appartement, logement locatif ou boutique : du conseil aux plans et à la 3D, jusqu’au suivi des artisans selon la mission retenue.": "Desde Anglet, te acompaño en tus proyectos de reforma, distribución y decoración en Biarritz, Bayona y la Costa Vasca. Casa, piso, vivienda de alquiler o tienda: desde el asesoramiento hasta los planos y el 3D, y el seguimiento de los profesionales según el servicio contratado.", "Un architecte d’intérieur à Anglet. Du dessin au chantier.": "Un interiorista en Anglet. Del dibujo a la obra.", "Architecture intérieure et décoration. Le bon accompagnement.": "Interiorismo y decoración. El acompañamiento adecuado.", "Concevoir votre rénovation. Un projet clair à chaque étape.": "Diseñar tu reforma. Un proyecto claro en cada etapa.", "Rénovation intérieure à Anglet. Une réalisation à découvrir.": "Reforma de interiores en Anglet. Un proyecto para descubrir.", "Votre projet d’architecture intérieure. Les premières questions.": "Tu proyecto de interiorismo. Las primeras preguntas.", "Votre projet à Anglet, Biarritz ou Bayonne. Parlons-en.": "Tu proyecto en Anglet, Biarritz o Bayona. Hablemos.", "Découvrir cette prestation →": "Descubrir este servicio →", "Découvrir la salle de bain rénovée à Anglet →": "Descubrir el baño reformado en Anglet →", "ANCRAGE": "ARRAIGO", "Un intérieur à votre image. Un regard ancré sur la Côte Basque.": "Un interior a tu medida. Una mirada arraigada en la Costa Vasca.", "Basé à Anglet, j’interviens à Biarritz, Bayonne et sur la Côte Basque pour vos projets d’architecture intérieure et de décoration. Rénovation d’un appartement, aménagement d’une maison neuve, logement locatif ou boutique : la mission se construit autour du lieu, de vos usages et de votre budget.": "Desde Anglet, trabajo en Biarritz, Bayona y la Costa Vasca en proyectos de interiorismo y decoración. Reforma de un piso, distribución de una casa nueva, vivienda de alquiler o tienda: el servicio se adapta al espacio, a tus usos y a tu presupuesto.", "Chaque projet commence par un échange sur sa localisation, sa surface et vos attentes. Les déplacements et le périmètre d’intervention sont précisés au devis.": "Cada proyecto empieza con una conversación sobre su ubicación, superficie y tus expectativas. Los desplazamientos y el alcance se concretan en el presupuesto.", "Aménager un logement locatif →": "Diseñar una vivienda de alquiler →", "Repenser tout votre intérieur →": "Replantear todo tu interior →", "Basé à Anglet · Projets à Biarritz, Bayonne et sur la Côte Basque": "En Anglet · Proyectos en Biarritz, Bayona y la Costa Vasca", "Projection d’ambiance intérieure : matières naturelles et lumière": "Propuesta de ambiente interior: materiales naturales y luz", "Benjamin Gonzalez, architecte d’intérieur à Anglet": "Benjamin Gonzalez, interiorista en Anglet", "Projection de chambre aux tons clairs, avec tête de lit en bois et textiles": "Propuesta de dormitorio en tonos claros, con cabecero de madera y textiles", "Visite conseil à Anglet, dès 350 € | Benjamin Gonzalez": "Asesoramiento en Anglet, desde 350 € | Benjamin Gonzalez", "Visite conseil en décoration et architecture intérieure à Anglet": "Visita de asesoramiento en decoración e interiorismo en Anglet", "Aménagement d’une pièce à Anglet | Benjamin Gonzalez": "Diseño de una estancia en Anglet | Benjamin Gonzalez", "Conception et aménagement d’une pièce à Anglet": "Diseño y distribución de una estancia en Anglet", "Conception globale d’intérieur, Côte Basque | Benjamin Gonzalez": "Diseño integral de interiores, Costa Vasca | Benjamin Gonzalez", "Architecture intérieure et rénovation à Anglet, Biarritz et Bayonne": "Interiorismo y reforma en Anglet, Biarritz y Bayona", "Suivi de chantier intérieur, Côte Basque | Benjamin Gonzalez": "Seguimiento de obra interior, Costa Vasca | Benjamin Gonzalez", "Préparation et suivi de chantier intérieur sur la Côte Basque": "Preparación y seguimiento de obra interior en la Costa Vasca", "Un regard extérieur. Des choix qui deviennent plus clairs.": "Una mirada externa. Decisiones más claras.", "Vous hésitez sur un agencement, une couleur ou la place d’un meuble ? La visite conseil permet de faire le point sur votre intérieur, sur place, avant de vous engager dans une conception plus détaillée.": "¿Dudas sobre una distribución, un color o la ubicación de un mueble? La visita de asesoramiento permite analizar tu interior, en el propio lugar, antes de iniciar un diseño más detallado.", "Quand une visite conseil vous aide": "Cuándo te ayuda una visita de asesoramiento", "Une pièce manque de cohérence, la circulation vous semble compliquée ou plusieurs idées se contredisent. Avant de choisir un revêtement ou de commander du mobilier, nous regardons ensemble les usages, les proportions et la lumière. L’objectif est de dégager une direction qui corresponde à votre manière de vivre et à votre budget.": "Una estancia carece de coherencia, la circulación resulta complicada o varias ideas se contradicen. Antes de elegir un revestimiento o comprar mobiliario, analizamos juntos los usos, las proporciones y la luz. El objetivo es definir una dirección que corresponda a tu manera de vivir y a tu presupuesto.", "Un rendez-vous chez vous, jusqu’à deux heures": "Una visita a tu vivienda, de hasta dos horas", "Je me déplace à Anglet et sur la Côte Basque, notamment à Biarritz et Bayonne. Vous me montrez les espaces concernés et les points qui vous interrogent. Nous abordons l’agencement, les couleurs, les matières et l’éclairage. Une synthèse écrite reprend les recommandations pour vous aider à poursuivre vos choix après le rendez-vous.": "Me desplazo por Anglet y la Costa Vasca, especialmente Biarritz y Bayona. Me muestras los espacios y las cuestiones que te preocupan. Abordamos la distribución, los colores, los materiales y la iluminación. Un resumen escrito recoge las recomendaciones para ayudarte a continuar tomando decisiones después de la visita.", "Préparer notre échange": "Preparar nuestra conversación", "Quelques photographies, un plan si vous en possédez un, vos inspirations et une première idée du budget suffisent à rendre le rendez-vous plus utile. Précisez aussi les éléments que vous souhaitez conserver. Une contrainte de délai, un achat déjà envisagé ou un usage particulier nous aident à fixer les priorités.": "Algunas fotografías, un plano si lo tienes, tus referencias y una primera idea del presupuesto hacen la visita más útil. Indica también los elementos que deseas conservar. Un plazo, una compra prevista o un uso específico nos ayudan a establecer las prioridades.", "Le conseil, puis la conception si nécessaire": "Asesoramiento y, si hace falta, diseño", "La visite conseil est une mission autonome. Elle ne comprend ni plans ni vues 3D. Si votre projet nécessite de comparer des implantations ou de développer une solution précise, la conception d’une pièce peut prolonger le travail. Une planche d’ambiance ou une sélection détaillée de mobilier peut également être proposée en complément, sur devis.": "La visita de asesoramiento es un servicio independiente. No incluye planos ni vistas 3D. Si necesitas comparar distribuciones o desarrollar una solución precisa, el diseño de una estancia puede dar continuidad al trabajo. También se pueden proponer un panel de inspiración o una selección detallada de mobiliario, bajo presupuesto.", "Une pièce. Une intention qui prend forme.": "Una estancia. Una intención que toma forma.", "Un salon, une chambre ou un espace de travail mérite d’être pensé dans son ensemble. Je relie les circulations, le mobilier, les matières et la lumière pour développer un aménagement cohérent avec vos usages.": "Un salón, un dormitorio o un espacio de trabajo merecen un diseño de conjunto. Relaciono la circulación, el mobiliario, los materiales y la luz para desarrollar una distribución coherente con tus usos.", "Partir de votre quotidien": "Partir de tu día a día", "Nous précisons d’abord ce qui fonctionne déjà et ce que vous souhaitez changer : un rangement insuffisant, une implantation à revoir, un éclairage peu adapté ou une ambiance qui ne vous ressemble plus. Le relevé et le plan d’état des lieux servent de base pour comprendre les proportions de la pièce.": "Primero concretamos lo que ya funciona y lo que deseas cambiar: almacenaje insuficiente, una distribución que revisar, iluminación poco adecuada o un ambiente que ya no te representa. La toma de medidas y el plano del estado actual sirven de base para comprender las proporciones de la estancia.", "Comparer, puis choisir": "Comparar y elegir", "Deux pistes d’agencement permettent d’explorer les possibilités de l’espace. Après présentation, nous retenons une direction et la développons. La planche d’ambiance et la palette de matières accompagnent les choix de revêtements, de mobilier et d’éclairage. Deux vues 3D de la proposition retenue vous aident à vous projeter.": "Dos propuestas de distribución permiten explorar las posibilidades del espacio. Tras la presentación, elegimos una dirección y la desarrollamos. El panel de inspiración y la paleta de materiales acompañan la elección de revestimientos, muebles e iluminación. Dos vistas 3D de la propuesta elegida te ayudan a visualizarla.", "Une mission définie avant de commencer": "Un servicio definido antes de empezar", "La base tarifaire concerne une pièce jusqu’à 20 m², hors étude technique complexe. Un cycle d’ajustements est prévu après présentation. Une cuisine, une salle de bain, des dessins d’exécution ou un mobilier sur mesure détaillé demandent un devis adapté : ces espaces et ces livrables ne sont pas assimilés automatiquement à la prestation de base.": "La tarifa de base corresponde a una estancia de hasta 20 m², sin estudio técnico complejo. Se incluye una ronda de ajustes tras la presentación. Una cocina, un baño, planos de ejecución o mobiliario a medida detallado requieren un presupuesto adaptado: estos espacios y documentos no se incluyen automáticamente en el servicio de base.", "À Anglet, Biarritz et Bayonne": "En Anglet, Biarritz y Bayona", "Basé à Anglet, j’accompagne des projets sur la Côte Basque. Pour commencer, indiquez la ville, la surface approximative, les éléments à conserver et votre échéance. Si plusieurs pièces doivent être coordonnées ou si une redistribution du logement est envisagée, une conception globale peut être plus adaptée.": "Desde Anglet, acompaño proyectos en la Costa Vasca. Para empezar, indica la ciudad, la superficie aproximada, los elementos que quieres conservar y el plazo previsto. Si se deben coordinar varias estancias o redistribuir la vivienda, un diseño integral puede ser más adecuado.", "Penser l’ensemble. Faire dialoguer les espaces.": "Pensar el conjunto. Relacionar los espacios.", "Pour une maison ou un appartement, la conception globale relie l’agencement et l’ambiance de chaque espace. Elle permet de construire une direction commune avant les choix techniques et la réalisation des travaux.": "En una casa o un piso, el diseño integral conecta la distribución y el ambiente de cada espacio. Permite definir una dirección común antes de las decisiones técnicas y de la ejecución de las obras.", "Repenser les volumes et les usages": "Replantear los volúmenes y los usos", "Le relevé et l’analyse des espaces concernés permettent de comprendre le logement : circulations, fonctions des pièces, rangements et relations entre les volumes. Les plans d’agencement traduisent les possibilités de redistribution. Nous les confrontons à vos priorités et à l’enveloppe envisagée pour les travaux.": "La toma de medidas y el análisis de los espacios permiten comprender la vivienda: circulaciones, funciones de cada estancia, almacenaje y relaciones entre volúmenes. Los planos de distribución traducen las posibilidades de reorganización. Las contrastamos con tus prioridades y con el presupuesto previsto para la obra.", "Une direction artistique cohérente": "Una dirección artística coherente", "Les matières, les couleurs et la lumière se répondent d’une pièce à l’autre. Les vues 3D portent sur les espaces clés définis au devis. Les principes de mobilier intégré et les implantations donnent une lecture d’ensemble de votre futur intérieur, tout en tenant compte de la manière dont vous souhaitez l’utiliser.": "Los materiales, los colores y la luz se relacionan de una estancia a otra. Las vistas 3D corresponden a los espacios clave definidos en el presupuesto. Los principios de mobiliario integrado y las implantaciones ofrecen una visión de conjunto de tu futuro interior, teniendo en cuenta cómo deseas utilizarlo.", "Honoraires et périmètre": "Honorarios y alcance", "La conception globale commence à 75 € par m², avec un minimum de mission de 3 000 €. Le montant dépend de la surface et de la complexité. Deux cycles d’ajustements de la proposition sont inclus dans le périmètre présenté, ainsi qu’une estimation prévisionnelle de l’enveloppe travaux. Cette estimation sert à orienter le projet ; elle ne remplace pas les devis des entreprises.": "El diseño integral parte de 75 € por m², con un mínimo de servicio de 3 000 €. El importe depende de la superficie y de la complejidad. El alcance presentado incluye dos rondas de ajustes y una estimación inicial del presupuesto de obra. Esta estimación orienta el proyecto; no sustituye a los presupuestos de las empresas.", "Préparer la suite du projet": "Preparar las siguientes etapas", "Le dossier technique détaillé, la consultation des entreprises et les démarches administratives sont des missions complémentaires sur devis. L’accompagnement du dessin au chantier peut prolonger la conception. À Anglet, Biarritz, Bayonne et sur la Côte Basque, nous définissons ces étapes avant l’engagement pour que les livrables et les honoraires soient clairs.": "El expediente técnico detallado, la consulta a empresas y los trámites administrativos son servicios adicionales bajo presupuesto. El acompañamiento del dibujo a la obra puede prolongar el diseño. En Anglet, Biarritz, Bayona y la Costa Vasca, definimos estas etapas antes del encargo para dejar claros los documentos y los honorarios.", "Du premier trait. Jusqu’aux finitions.": "Desde el primer trazo. Hasta los acabados.", "Un projet dessiné a besoin d’une préparation précise pour devenir un lieu construit. Cette mission prolonge la conception par le dossier technique, la consultation des entreprises et un accompagnement pendant les travaux, selon le périmètre convenu.": "Un proyecto dibujado necesita una preparación precisa para convertirse en un espacio construido. Este servicio prolonga el diseño mediante el expediente técnico, la consulta a empresas y el acompañamiento durante las obras, según el alcance acordado.", "Préciser ce qui doit être réalisé": "Precisar lo que debe realizarse", "Les plans détaillés, calepinages et détails de menuiseries sur mesure sont établis selon la mission. Le travail se coordonne avec l’architecte, le constructeur ou les bureaux d’études du projet lorsque ces intervenants sont concernés. Les documents et les responsabilités de chacun sont définis dans le devis.": "Los planos detallados, despieces y detalles de carpintería a medida se elaboran según el servicio contratado. El trabajo se coordina con el arquitecto, el constructor o los equipos de ingeniería del proyecto cuando intervienen. Los documentos y las responsabilidades de cada participante se definen en el presupuesto.", "Préparer l’intervention des entreprises": "Preparar la intervención de las empresas", "La consultation et l’analyse des devis aident à confronter la conception à sa réalisation. La planification permet d’organiser les interventions. Nous précisons les choix à arrêter, les points à discuter avec les entreprises et la façon dont le projet doit avancer pour limiter les décisions prises dans l’urgence.": "La consulta y el análisis de presupuestos ayudan a contrastar el diseño con su ejecución. La planificación organiza las intervenciones. Precisamos las decisiones pendientes, los puntos que tratar con las empresas y la manera de avanzar para limitar las decisiones tomadas con urgencia.", "Accompagner les travaux": "Acompañar las obras", "Les visites de chantier et les comptes rendus servent à suivre l’avancement et à partager les points à traiter. La fréquence des visites est adaptée au projet et fixée dans la mission. L’accompagnement peut comprendre la réception et le suivi des réserves. Il concerne une rénovation intérieure ou l’agencement d’une maison neuve.": "Las visitas de obra y los informes permiten seguir el avance y comunicar los puntos que resolver. La frecuencia de las visitas se adapta al proyecto y queda fijada en el servicio. El acompañamiento puede incluir la recepción y el seguimiento de las observaciones pendientes. Se aplica a una reforma interior o al acondicionamiento de una casa nueva.", "Un devis adapté à votre chantier": "Un presupuesto adaptado a tu obra", "Les honoraires dépendent de l’ampleur des travaux, de leur durée et de la fréquence des visites. La conception et le suivi sont identifiés séparément au devis. Pour un projet à Anglet, Biarritz, Bayonne ou sur la Côte Basque, transmettez les plans disponibles, la nature des travaux et votre calendrier pour que nous précisions l’accompagnement utile.": "Los honorarios dependen del alcance de los trabajos, de su duración y de la frecuencia de las visitas. El diseño y el seguimiento se identifican por separado en el presupuesto. Para un proyecto en Anglet, Biarritz, Bayona o la Costa Vasca, envía los planos disponibles, la naturaleza de los trabajos y el calendario previsto para concretar el acompañamiento útil.", "Aménagement locatif : confort et usage au quotidien": "Diseño de una vivienda de alquiler: confort y uso cotidiano", "Pour un logement meublé ou une location saisonnière, l’aménagement doit répondre aux besoins des occupants et aux contraintes du propriétaire. Je travaille les circulations, les rangements, le mobilier et l’ambiance pour composer un lieu accueillant. Les choix de matières tiennent compte de la résistance, de l’entretien et du budget.": "En una vivienda amueblada o un alquiler vacacional, el diseño debe responder a las necesidades de los ocupantes y del propietario. Trabajo la circulación, el almacenaje, el mobiliario y el ambiente para crear un lugar acogedor. Los materiales se eligen teniendo en cuenta su resistencia, mantenimiento y presupuesto.", "Un lieu cohérent, jusque dans les détails": "Un espacio coherente, hasta en los detalles", "Avant les achats, nous précisons les usages : nombre de couchages prévu, besoin de rangement, espaces de repas ou de travail, et éléments à conserver. Le plan d’agencement permet de vérifier les implantations. Couleurs, revêtements et éclairage donnent ensuite une direction commune aux différentes pièces.": "Antes de las compras, concretamos los usos: número previsto de plazas, necesidades de almacenaje, zonas para comer o trabajar y elementos que conservar. El plano de distribución permite comprobar las implantaciones. Colores, revestimientos e iluminación dan después una dirección común a las distintas estancias.", "Une mission adaptée à votre bien": "Un servicio adaptado a tu vivienda", "Une visite conseil peut aider à orienter un logement déjà équipé. La conception d’une pièce permet de développer un espace particulier. Pour repenser plusieurs pièces et les coordonner, la conception globale offre une vision d’ensemble. Si les travaux nécessitent une préparation technique et un suivi, cet accompagnement fait l’objet d’une mission distincte sur devis.": "Una visita de asesoramiento puede orientar una vivienda ya equipada. El diseño de una estancia desarrolla un espacio concreto. Para replantear y coordinar varias estancias, el diseño integral ofrece una visión de conjunto. Si las obras requieren preparación técnica y seguimiento, ese acompañamiento se establece en un servicio independiente bajo presupuesto.", "À Anglet et sur la Côte Basque": "En Anglet y la Costa Vasca", "Basé à Anglet, j’accompagne des projets à Biarritz, Bayonne et sur la Côte Basque. Pour décrire votre besoin, indiquez la ville, la surface, le type de logement, les meubles conservés et votre échéance. Des photographies et un plan existant permettent de mieux comprendre les possibilités avant de définir la mission.": "Desde Anglet, acompaño proyectos en Biarritz, Bayona y la Costa Vasca. Para describir tu necesidad, indica la ciudad, la superficie, el tipo de vivienda, los muebles que conservarás y el plazo. Fotografías y un plano existente permiten comprender mejor las posibilidades antes de definir el servicio.", "Préparer votre projet": "Preparar tu proyecto", "L’aménagement intérieur se construit à partir du logement et de son utilisation prévue. La prestation porte sur la conception et, selon le devis, l’accompagnement des travaux. Les possibilités de mise en location et les autorisations éventuelles sont à vérifier séparément pour votre bien ; aucun revenu locatif n’est garanti par l’aménagement.": "El diseño interior parte de la vivienda y de su uso previsto. El servicio se centra en la concepción y, según el presupuesto, en el acompañamiento de las obras. La posibilidad de alquilar y las autorizaciones necesarias se deben comprobar por separado para cada inmueble; el diseño no garantiza ingresos de alquiler.", "Aménagement de location saisonnière, Pays Basque | Benjamin Gonzalez": "Diseño de alquiler vacacional, País Vasco | Benjamin Gonzalez", "Aménagement de logements locatifs et saisonniers au Pays Basque": "Diseño de viviendas de alquiler y vacacionales en el País Vasco", "Le locatif mérite aussi le sens du détail.": "El alquiler también merece atención al detalle.", "Un logement accueillant, simple à vivre et cohérent dans ses choix : je vous accompagne dans l’aménagement intérieur de votre location à Anglet et sur la Côte Basque.": "Una vivienda acogedora, cómoda y coherente: te acompaño en el diseño interior de tu alquiler en Anglet y en la Costa Vasca.", "Projection d’aménagement d’un logement locatif : cuisine claire et table ronde": "Propuesta para una vivienda de alquiler: cocina clara y mesa redonda", "Projection d’ambiance pour un logement locatif — visuel de conception.": "Propuesta de ambiente para una vivienda de alquiler — visualización de diseño.", "Rénovation de salle de bain à Anglet | Benjamin Gonzalez": "Reforma de un baño en Anglet | Benjamin Gonzalez", "Une réalisation. Un lieu concret.": "Un proyecto realizado. Un espacio concreto.", "Découvrez une salle de bain rénovée à Anglet, présentée parmi les réalisations de Benjamin Gonzalez, architecte d’intérieur sur la Côte Basque.": "Descubre un baño reformado en Anglet, entre los proyectos de Benjamin Gonzalez, interiorista en la Costa Vasca.", "Salle de bain rénovée à Anglet, réalisation de Benjamin Gonzalez": "Baño reformado en Anglet, proyecto de Benjamin Gonzalez", "Salle de bain — Anglet. Photographie de la réalisation.": "Baño — Anglet. Fotografía del proyecto realizado.", "Une salle de bain rénovée à Anglet": "Un baño reformado en Anglet", "Cette salle de bain fait partie des réalisations présentées par Benjamin Gonzalez. La photographie montre le résultat construit à Anglet : une façon concrète de découvrir le travail d’agencement et de décoration, au-delà des projections d’ambiance.": "Este baño forma parte de los proyectos presentados por Benjamin Gonzalez. La fotografía muestra el resultado construido en Anglet: una forma concreta de descubrir el trabajo de distribución y decoración, más allá de las propuestas de ambiente.", "Chaque salle de bain a ses usages et ses contraintes. Pour votre propre projet, nous partirons des dimensions du lieu, des équipements que vous souhaitez conserver ou remplacer, de vos attentes et du budget envisagé.": "Cada baño tiene sus usos y condicionantes. Para tu proyecto, partiremos de las dimensiones del espacio, de los equipos que deseas conservar o sustituir, de tus expectativas y del presupuesto previsto.", "Votre salle de bain : définir une mission précise": "Tu baño: definir un servicio preciso", "La conception d’une salle de bain demande un devis adapté au niveau d’étude nécessaire. Les points à travailler peuvent concerner l’implantation, les rangements, les revêtements ou l’éclairage. Le dossier technique et le suivi des travaux sont précisés séparément selon le besoin.": "El diseño de un baño requiere un presupuesto adaptado al estudio necesario. Se pueden trabajar la distribución, el almacenaje, los revestimientos o la iluminación. El expediente técnico y el seguimiento de obra se concretan por separado según la necesidad.", "Pour commencer, envoyez quelques photographies, un plan si vous en avez un, la ville du projet et une description de ce qui doit évoluer. Nous pourrons ainsi définir les premières priorités et le périmètre de l’accompagnement.": "Para empezar, envía algunas fotografías, un plano si lo tienes, la ciudad del proyecto y una descripción de lo que quieres cambiar. Así podremos definir las primeras prioridades y el alcance del acompañamiento.", "Découvrir la conception d’une pièce →": "Descubrir el diseño de una estancia →", "Une salle de bain à rénover ?": "¿Quieres reformar un baño?", "Découvrez la réalisation à Anglet": "Descubre el proyecto realizado en Anglet", "Accueil": "Inicio", "Choisir l’accompagnement adapté": "Elegir el acompañamiento adecuado", "Aménagement d’un logement locatif": "Diseño de una vivienda de alquiler", "Logements locatifs": "Viviendas de alquiler", "Salle de bain à Anglet": "Baño en Anglet", "Fil d’Ariane": "Ruta de navegación", "Prestations et réalisation": "Servicios y proyecto realizado", "Visite conseil à Anglet, Biarritz et Bayonne dès 350 € : agencement, couleurs, matières et éclairage. Rendez-vous sur place et synthèse écrite.": "Asesoramiento en Anglet, Biarritz y Bayona desde 350 €: distribución, colores, materiales e iluminación. Visita al lugar y resumen escrito.", "Conception d’une pièce à Anglet et sur la Côte Basque : agencement, ambiance et vues 3D. Dès 1 200 € jusqu’à 20 m², selon le périmètre.": "Diseño de una estancia en Anglet y la Costa Vasca: distribución, ambiente y vistas 3D. Desde 1 200 € hasta 20 m², según el alcance.", "Architecte d’intérieur à Anglet : conception globale à Biarritz et Bayonne. Plans, matières et 3D dès 75 €/m². Minimum de mission : 3 000 €.": "Interiorista en Anglet: diseño integral en Biarritz y Bayona. Planos, materiales y 3D desde 75 €/m². Mínimo de servicio: 3 000 €.", "Préparation et suivi de chantier intérieur à Anglet, Biarritz et Bayonne. Dossier technique, consultation des entreprises et visites, sur devis.": "Preparación y seguimiento de obra interior en Anglet, Biarritz y Bayona. Expediente técnico, consulta a empresas y visitas, bajo presupuesto.", "Aménagement de logements locatifs et saisonniers à Anglet et sur la Côte Basque. Agencement, mobilier et décoration : une mission adaptée à votre bien.": "Diseño de viviendas de alquiler y vacacionales en Anglet y la Costa Vasca. Distribución, mobiliario y decoración: un servicio adaptado a tu vivienda.", "Découvrez une salle de bain rénovée à Anglet, réalisation de Benjamin Gonzalez. Architecture intérieure et décoration sur la Côte Basque.": "Descubre un baño reformado en Anglet, proyecto de Benjamin Gonzalez. Interiorismo y decoración en la Costa Vasca.", "Benjamin Gonzalez utilise vos informations pour répondre à votre demande et préparer un éventuel devis. Les champs marqués * sont obligatoires. Le message est transmis par Web3Forms à ma messagerie. Pour toute question sur vos données ou exercer vos droits, écrivez à gonzalez_benjamin@outlook.fr.": "Benjamin Gonzalez utiliza tus datos para responder a tu solicitud y preparar un posible presupuesto. Los campos marcados con * son obligatorios. Web3Forms transmite el mensaje a mi correo electrónico. Para cualquier consulta sobre tus datos o para ejercer tus derechos, escribe a gonzalez_benjamin@outlook.fr.", "Mentions légales": "Aviso legal", "Données personnelles": "Datos personales", "Gestion de vos données": "Gestión de tus datos", "Mentions légales et données personnelles": "Aviso legal y datos personales", "Mentions légales et données personnelles | Benjamin Gonzalez": "Aviso legal y datos personales | Benjamin Gonzalez", "INFORMATIONS DU SITE": "INFORMACIÓN DEL SITIO", "Dernière mise à jour : 30 septembre 2026.": "Última actualización: 30 de septiembre de 2026.", "Éditeur du site": "Editor del sitio", "Benjamin Gonzalez — Entrepreneur individuel (EI), sous le régime de la microentreprise.": "Benjamin Gonzalez — Empresario individual (EI), acogido al régimen francés de microempresa.", "Activité : architecture intérieure, aménagement et décoration.": "Actividad: arquitectura de interiores, distribución y decoración.", "Adresse de domiciliation : 51 Rue Henri Reneric, 64600 Anglet, France.": "Domicilio de la empresa: 51 Rue Henri Reneric, 64600 Anglet, Francia.", "SIREN : 949 200 950 — SIRET : 94920095000010.": "SIREN: 949 200 950 — SIRET: 94920095000010.", "Téléphone :": "Teléfono:", "E-mail :": "Correo electrónico:", "Directeur de la publication : Benjamin Gonzalez.": "Director de la publicación: Benjamin Gonzalez.", "TVA non applicable, article L. 223-3 du Code des impositions des biens et des services (CIBS).": "IVA no aplicable, artículo L. 223-3 del Code des impositions des biens et des services (CIBS) francés.", "Hébergement": "Alojamiento", "Le site est hébergé par GitHub, Inc., au moyen du service GitHub Pages.": "El sitio está alojado por GitHub, Inc., mediante el servicio GitHub Pages.", "88 Colin P. Kelly Jr. St., San Francisco, CA 94107, États-Unis.": "88 Colin P. Kelly Jr. St., San Francisco, CA 94107, Estados Unidos.", "Contenus et crédits": "Contenidos y créditos", "Photographies, croquis, plans, projections et logo : Benjamin Gonzalez. Les visuels sont publiés avec les droits déclarés par leur auteur. Les projections et images d’ambiance ne constituent pas, à elles seules, des photographies de réalisations livrées.": "Fotografías, bocetos, planos, proyecciones y logotipo: Benjamin Gonzalez. Las imágenes se publican con los derechos declarados por su autor. Las proyecciones y las imágenes de ambiente no constituyen, por sí solas, fotografías de proyectos entregados.", "Toute réutilisation des contenus doit respecter les droits des titulaires concernés. Pour une demande d’autorisation, contactez Benjamin Gonzalez. La citation attribuée à Frank Lloyd Wright conserve son attribution.": "Toda reutilización de los contenidos debe respetar los derechos de sus titulares. Para solicitar una autorización, contacta con Benjamin Gonzalez. La cita atribuida a Frank Lloyd Wright mantiene su atribución.", "Responsable et informations recueillies": "Responsable e información recogida", "Benjamin Gonzalez EI, aux coordonnées indiquées ci-dessus, traite les demandes adressées par le formulaire. Celui-ci recueille le nom, l’adresse e-mail, le message et, s’ils sont renseignés, le téléphone et le type de projet. Des données techniques, dont l’adresse IP et la date d’envoi, peuvent également être traitées par le prestataire pour transmettre le message et prévenir les abus.": "Benjamin Gonzalez EI, con los datos de contacto indicados anteriormente, gestiona las solicitudes enviadas mediante el formulario. Este recoge el nombre, el correo electrónico, el mensaje y, si se facilitan, el teléfono y el tipo de proyecto. El proveedor también puede tratar datos técnicos, como la dirección IP y la fecha de envío, para transmitir el mensaje y prevenir abusos.", "Les champs marqués * sont obligatoires pour envoyer et traiter la demande. Les autres champs sont facultatifs. Si les champs obligatoires ne sont pas renseignés, le formulaire ne peut pas être envoyé.": "Los campos marcados con * son obligatorios para enviar y tramitar la solicitud. Los demás son opcionales. Si no se cumplimentan los campos obligatorios, el formulario no puede enviarse.", "Finalités et bases légales": "Finalidades y bases jurídicas", "Les données servent à répondre à votre demande, échanger sur votre projet et préparer un éventuel devis. Pour une demande de prestation, le traitement repose sur les mesures précontractuelles prises à votre demande. La réponse aux autres demandes et la prévention des abus reposent sur l’intérêt légitime à gérer les échanges et assurer la sécurité du service.": "Los datos sirven para responder a tu solicitud, hablar sobre tu proyecto y preparar un posible presupuesto. Para una solicitud de servicio, el tratamiento se basa en las medidas precontractuales adoptadas a petición tuya. La respuesta a otras consultas y la prevención de abusos se basan en el interés legítimo de gestionar las comunicaciones y garantizar la seguridad del servicio.", "Le formulaire ne comporte pas d’inscription à une newsletter. La transmission d’une demande ne vaut pas consentement à recevoir des campagnes publicitaires.": "El formulario no incluye ninguna suscripción a un boletín. El envío de una solicitud no constituye consentimiento para recibir campañas publicitarias.", "Destinataires et prestataires": "Destinatarios y proveedores", "Les demandes sont destinées à Benjamin Gonzalez. Leur traitement implique aussi les services nécessaires à leur transmission, réception et sécurisation : Web3Forms, exploité par Web3Creative, la messagerie Microsoft Outlook, ainsi que leurs prestataires techniques habilités.": "Las solicitudes están destinadas a Benjamin Gonzalez. Su tratamiento también requiere los servicios necesarios para transmitirlas, recibirlas y protegerlas: Web3Forms, gestionado por Web3Creative, el correo Microsoft Outlook y sus proveedores técnicos autorizados.", "Web3Forms décrit notamment des prestataires d’infrastructure et de filtrage antispam. Les listes et les conditions actuelles sont consultables dans ses documents ci-dessous.": "Web3Forms describe, entre otros, proveedores de infraestructura y de filtrado antispam. Las listas y las condiciones vigentes pueden consultarse en los documentos siguientes.", "Politique de confidentialité Web3Forms": "Política de privacidad de Web3Forms", "Accord de traitement Web3Forms": "Acuerdo de tratamiento de Web3Forms", "Politique de confidentialité Microsoft": "Política de privacidad de Microsoft", "Durées de conservation": "Plazos de conservación", "Pour les demandes de projet qui ne donnent pas lieu à un contrat, les données utiles sont conservées pendant trois ans au maximum à compter de leur collecte ou du dernier contact venant du demandeur. Elles peuvent être supprimées plus tôt lorsqu’elles ne sont plus nécessaires. En cas de contrat, les documents nécessaires sont conservés selon les obligations applicables, notamment comptables, fiscales et de preuve, avec un accès limité à cet archivage.": "Para las solicitudes de proyecto que no den lugar a un contrato, los datos útiles se conservan durante un máximo de tres años desde su recogida o desde el último contacto iniciado por la persona solicitante. Pueden eliminarse antes si ya no son necesarios. En caso de contrato, los documentos necesarios se conservan conforme a las obligaciones aplicables, especialmente contables, fiscales y probatorias, con acceso limitado al archivo.", "Web3Forms annonce une conservation maximale des soumissions de trois ans après leur envoi, sauf durée plus courte applicable au compte ou suppression anticipée. Les journaux techniques des prestataires suivent leurs politiques de conservation propres pour le fonctionnement et la sécurité des services.": "Web3Forms indica que conserva los envíos durante un máximo de tres años desde su recepción, salvo que se aplique al plan un plazo más breve o se eliminen antes. Los registros técnicos de los proveedores siguen sus respectivas políticas de conservación para el funcionamiento y la seguridad de los servicios.", "Transferts internationaux": "Transferencias internacionales", "Certains prestataires peuvent traiter les données en dehors de l’Union européenne. Web3Forms indique opérer depuis l’Inde et prévoit dans son accord de traitement des garanties, notamment les clauses contractuelles types de la Commission européenne. Microsoft décrit ses lieux de traitement et mécanismes de transfert dans sa déclaration de confidentialité. Les documents liés ci-dessus permettent de consulter ces informations et les garanties annoncées ; vous pouvez aussi en demander une copie ou des précisions à Benjamin Gonzalez.": "Algunos proveedores pueden tratar los datos fuera de la Unión Europea. Web3Forms indica que opera desde la India y establece garantías en su acuerdo de tratamiento, entre ellas las cláusulas contractuales tipo de la Comisión Europea. Microsoft describe sus lugares de tratamiento y sus mecanismos de transferencia en su declaración de privacidad. Los documentos enlazados anteriormente permiten consultar esta información y las garantías indicadas; también puedes solicitar una copia o información adicional a Benjamin Gonzalez.", "Vos droits": "Tus derechos", "Vous pouvez demander l’accès à vos données, leur rectification, leur effacement ou la limitation de leur traitement. Vous disposez également, lorsque les conditions sont réunies, du droit à la portabilité et du droit d’opposition pour les traitements fondés sur l’intérêt légitime. Ces droits s’exercent dans les limites prévues par la réglementation.": "Puedes solicitar el acceso a tus datos, su rectificación, su supresión o la limitación de su tratamiento. También dispones, cuando se cumplan las condiciones, del derecho a la portabilidad y del derecho de oposición a los tratamientos basados en el interés legítimo. Estos derechos se ejercen dentro de los límites previstos por la normativa.", "Pour exercer vos droits ou poser une question sur vos données :": "Para ejercer tus derechos o preguntar sobre tus datos:", "Vous pouvez également adresser une réclamation à la": "También puedes presentar una reclamación ante la", "Navigation, langue et services techniques": "Navegación, idioma y servicios técnicos", "Le code livré n’intègre pas de traceur publicitaire ni d’outil de mesure d’audience. Votre choix FR/ES est mémorisé dans le stockage local de votre navigateur, sous la clé bg-language, afin de conserver la langue sélectionnée. Vous pouvez l’effacer dans les paramètres de votre navigateur.": "El código entregado no incluye rastreadores publicitarios ni herramientas de medición de audiencia. Tu elección FR/ES se guarda en el almacenamiento local del navegador, con la clave bg-language, para conservar el idioma elegido. Puedes borrarla en la configuración del navegador.", "Les polices sont chargées depuis Google Fonts : votre navigateur établit une connexion avec Google et lui transmet notamment votre adresse IP. GitHub Pages reçoit les données techniques nécessaires à l’hébergement et à la sécurité du site. Ces fournisseurs décrivent leurs traitements, leurs destinataires, leurs durées ou critères de conservation et leurs transferts dans les politiques suivantes.": "Las fuentes se cargan desde Google Fonts: tu navegador se conecta con Google y le transmite, entre otros datos, tu dirección IP. GitHub Pages recibe los datos técnicos necesarios para alojar y proteger el sitio. Estos proveedores describen sus tratamientos, destinatarios, plazos o criterios de conservación y transferencias en las políticas siguientes.", "Confidentialité GitHub": "Privacidad de GitHub", "Confidentialité Google": "Privacidad de Google", "Informations Google Fonts": "Información de Google Fonts", "Informations légales et gestion des données personnelles du site Benjamin Gonzalez, architecte d’intérieur à Anglet.": "Información legal y gestión de los datos personales del sitio de Benjamin Gonzalez, interiorista en Anglet.", "Photographies, croquis, plans, projections et logo : Benjamin Gonzalez. Les projections et images d’ambiance ne constituent pas, à elles seules, des photographies de réalisations livrées.": "Fotografías, bocetos, planos, proyecciones y logotipo: Benjamin Gonzalez. Las proyecciones y las imágenes de ambiente no constituyen, por sí solas, fotografías de proyectos entregados.", "Le site n’intègre pas de traceur publicitaire ni d’outil de mesure d’audience. Votre choix FR/ES est mémorisé dans le stockage local de votre navigateur, sous la clé bg-language, afin de conserver la langue sélectionnée. Vous pouvez l’effacer dans les paramètres de votre navigateur.": "El sitio no incluye rastreadores publicitarios ni herramientas de medición de audiencia. Tu elección FR/ES se guarda en el almacenamiento local del navegador, con la clave bg-language, para conservar el idioma elegido. Puedes borrarla en la configuración del navegador.", "Salon aux assises généreuses, canapé vert et matières naturelles": "Salón con asientos generosos, sofá verde y materiales naturales", "ÉTUDE D’AMBIANCE · UN SALON ENVELOPPANT": "ESTUDIO DE AMBIENTE · UN SALÓN ACOGEDOR", "Utilisation de vos données et exercice de vos droits": "Uso de tus datos y ejercicio de tus derechos", "Fermer les mentions légales": "Cerrar el aviso legal", "Explorer les 2 autres vues": "Explorar las otras 2 vistas", "Projet d’intérieur · Chêne, courbes et lumière": "Proyecto de interior · Roble, curvas y luz", "Visualisation de conception": "Visualización del proyecto", "Fermer la page": "Cerrar la página", "Explorer les 3 autres vues": "Explorar las otras 3 vistas", "La justesse des lignes.": "La precisión de las líneas.", "Au cœur de la vie.": "En el corazón de la vida.", "Agrandir : La justesse des lignes.": "Ampliar: La precisión de las líneas.", "Agrandir : Au cœur de la vie.": "Ampliar: En el corazón de la vida.", "Agrandir : Chêne, lumière et matières naturelles.": "Ampliar: Roble, luz y materiales naturales.", "Chêne, lumière et matières naturelles. · Visualisation de conception": "Roble, luz y materiales naturales. · Visualización de diseño", "Cuisine en chêne avec îlot en quartz blanc et séparation en briques de verre": "Cocina de roble con isla de cuarzo blanco y separación de bloques de vidrio", "Salle à manger ouverte sur une cuisine avec îlot blanc, arches et claustra en terre cuite": "Comedor abierto a una cocina con isla blanca, arcos y celosía de terracota", "Cuisine en chêne avec îlot en quartz blanc, suspensions et tabourets": "Cocina de roble con isla de cuarzo blanco, lámparas colgantes y taburetes", "Cuisine et îlot en quartz blanc, chêne et briques de verre ondulées": "Cocina e isla de cuarzo blanco, roble y bloques de vidrio ondulados", "Îlot blanc ouvert sur la salle à manger, arches et briques de verre": "Isla blanca abierta al comedor, arcos y bloques de vidrio", "Salon lumineux avec bibliothèque en chêne, assises vertes et grandes baies vitrées": "Salón luminoso con biblioteca de roble, asientos verdes y grandes ventanales"};
 let language='fr';
 const textBindings=[], attributeBindings=[];
 const walker=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
  const node=walker.currentNode;
  if(node.parentElement.closest('script,style,.language-switch'))continue;
  const original=node.nodeValue, key=original.trim();
  if(Object.hasOwn(translations,key))textBindings.push({node,original,key});
 }
 document.querySelectorAll('[alt],[aria-label],[placeholder],meta[name="description"],meta[property="og:title"],meta[property="og:description"]').forEach(el=>{
  if(el.closest('.language-switch') && el.matches('button'))return;
  ['alt','aria-label','placeholder','content'].forEach(name=>{
   const original=el.getAttribute(name);
   if(original && Object.hasOwn(translations,original))attributeBindings.push({el,name,original});
  });
 });
 window.siteText=key=>language==='es'?(translations[key]||key):key;
 function setLanguage(next){
  language=next==='es'?'es':'fr';document.documentElement.lang=language;
  textBindings.forEach(({node,original,key})=>{node.nodeValue=original.replace(key,window.siteText(key));});
  attributeBindings.forEach(({el,name,original})=>el.setAttribute(name,window.siteText(original)));
  const status=document.getElementById('status');
  if(status)status.textContent='';
  const send=document.getElementById('send-btn');
  if(send)send.textContent=window.siteText(send.disabled?'Envoi en cours…':'Envoyer le message');
  document.querySelectorAll('[data-lang]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===language)));
  try{localStorage.setItem('bg-language',language);}catch(e){}
 }
 document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>{
  setLanguage(button.dataset.lang);
  try{const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);}catch(e){}
 }));
 let initial=new URLSearchParams(location.search).get('lang');
 if(!['fr','es'].includes(initial)){try{initial=localStorage.getItem('bg-language');}catch(e){}}
 setLanguage(initial);
 document.querySelector('.language-switch').hidden=false;
})();
