document.getElementById('year').textContent = new Date().getFullYear();

/* Barre de navigation : fond opaque au défilement */
(function(){
  const nav = document.getElementById('nav');
  const jauge = document.querySelector('#progress span');
  let dernier = window.scrollY;
  let enCours = false;

  function actualiser(){
    const y = window.scrollY;

    // Fond plus opaque dès qu'on quitte le haut de page
    nav.classList.toggle('is-stuck', y > 40);

    // La barre s'efface quand on descend, réapparaît quand on remonte
    if (y > 260 && y > dernier + 6)      nav.classList.add('is-hidden');
    else if (y < dernier - 6 || y < 120) nav.classList.remove('is-hidden');
    dernier = y;

    // Repère de lecture
    if (jauge) {
      const total = document.documentElement.scrollHeight - window.innerHeight;
      jauge.style.width = (total > 0 ? Math.min(y / total, 1) * 100 : 0) + '%';
    }
    enCours = false;
  }

  window.addEventListener('scroll', () => {
    if (!enCours) { enCours = true; requestAnimationFrame(actualiser); }
  }, { passive:true });

  actualiser();
})();

/* Horodatage d'ouverture du formulaire : un robot qui répond en moins de
   trois secondes sera refusé côté serveur. */
(function(){
  const champ = document.getElementById('ouvert_a');
  if (champ) champ.value = String(Date.now());
})();

/* Apparition progressive. Les cartes de prestations sont volontairement
   exclues : elles utilisent l'empilement au défilement, incompatible avec
   une transformation appliquée au même élément.
   On marque les blocs, puis on les révèle à l'approche. */
(function(){
  const cibles = document.querySelectorAll(
    '.section-body > h2, .origine-grid > div, .origine-grid figure, ' +
    '.tools, .band figure, .project, .contact-lines, .form, .tier-note, .section-body > p'
  );
  cibles.forEach((el, i) => {
    el.classList.add('appear');
    el.classList.add('d' + (i % 3 + 1));
  });

  const doux = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (doux || !('IntersectionObserver' in window)) {
    cibles.forEach(el => el.classList.add('seen'));
    return;
  }
  const obs = new IntersectionObserver((entrees) => {
    entrees.forEach(e => {
      if (e.isIntersecting) { e.target.classList.add('seen'); obs.unobserve(e.target); }
    });
  }, { rootMargin: '0px 0px -12% 0px', threshold: 0.12 });
  cibles.forEach(el => obs.observe(el));
})();

/* Si une image ne se charge pas (blocage inter-domaine, fichier absent),
   on remplace la balise par un cadre lisible au lieu d'une icône cassée. */
document.querySelectorAll('img[src]').forEach(img => {
  const fallback = () => {
    if (img.dataset.handled) return;
    img.dataset.handled = '1';
    const box = document.createElement('div');
    box.className = 'img-failed';
    box.setAttribute('data-label', img.alt || window.siteText('Image indisponible'));
    box.style.aspectRatio = getComputedStyle(img).aspectRatio || 'auto';
    if (img.closest('.hero-media')) box.style.height = '100%';
    img.replaceWith(box);
  };
  img.addEventListener('error', fallback);
  if (img.complete && img.naturalWidth === 0) fallback();
});

/* Envoi du formulaire sans rechargement de page */
const form = document.getElementById('contact-form');
const status = document.getElementById('status');
const btn = document.getElementById('send-btn');

form?.addEventListener('submit', async (e) => {
  e.preventDefault();
  if (document.body.dataset.preview === 'true') {
    status.textContent = window.siteText('Ceci est un aperçu. Pour me contacter, utilisez les liens e-mail ou téléphone.');
    return;
  }
  status.className = 'status';
  status.textContent = '';

  if (!form.nom.value.trim() || !form.email.value.trim() || !form.message.value.trim()) {
    status.className = 'status err';
    status.textContent = window.siteText("Il manque le nom, l'e-mail ou le message.");
    return;
  }
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email.value)) {
    status.className = 'status err';
    status.textContent = window.siteText("L'adresse e-mail n'est pas valide.");
    return;
  }

  if (form.elements.namedItem('site').value || form.elements.namedItem('botcheck').checked) return;
  if (btn.disabled) return;
  btn.disabled = true;
  const label = btn.textContent;
  btn.textContent = window.siteText('Envoi en cours…');

  try {
    const payload = Object.fromEntries(new FormData(form));
    payload.name = payload.nom;
    payload.phone = payload.tel;
    payload.langue = document.documentElement.lang;
    delete payload.nom;
    delete payload.tel;
    delete payload.site;
    delete payload.ouvert_a;
    delete payload.botcheck;
    const res = await fetch(form.action, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' }
    });
    const data = await res.json().catch(() => ({}));

    if (res.ok && data.success === true) {
      form.reset();
      document.getElementById('ouvert_a').value = String(Date.now());
      status.className = 'status ok';
      status.textContent = window.siteText('Message envoyé. Je vous réponds sous 48 heures ouvrées.');
    } else {
      throw new Error(data.error || 'Envoi impossible');
    }
  } catch (err) {
    status.className = 'status err';
    status.innerHTML = window.siteText("L'envoi a échoué. Écrivez-moi directement à") + ' <a href="mailto:gonzalez_benjamin@outlook.fr">gonzalez_benjamin@outlook.fr</a> ' + window.siteText("ou appelez le") + " 06 52 05 29 04.";
  } finally {
    btn.disabled = false;
    btn.textContent = window.siteText('Envoyer le message');
  }
});

